use redb::ReadableTable;

use crate::domain::{
    AdminAuditRecord, Error, Id, RULE_LOCALE_LIMIT, RULE_TEXT_LIMIT, Result, Rule, RuleTranslation,
};

use super::schema::{ADMIN_AUDIT, RULE_TRANSLATIONS, RULES};
use super::{RedbStore, decode, encode};

pub(super) fn admin_audit(
    store: &RedbStore,
    actor_account_id: Id,
    action: &str,
    target_type: &str,
    target_id: &str,
    now_ms: u64,
) -> Result<AdminAuditRecord> {
    let record = AdminAuditRecord {
        id: store.next_id(),
        actor_account_id,
        action: action.to_string(),
        target_type: target_type.to_string(),
        target_id: target_id.to_string(),
        created_at_ms: now_ms,
    };
    let write = store.begin_write()?;
    super::admin_scan_ctx::audit_append(&write, &record)?;
    write.commit()?;
    Ok(record)
}

pub(super) fn admin_audit_log(store: &RedbStore, limit: usize) -> Result<Vec<AdminAuditRecord>> {
    let read = store.begin_read()?;
    let log = read.open_table(ADMIN_AUDIT)?;
    let mut out = Vec::new();
    for entry in log.range(0u64..=u64::MAX)?.rev() {
        let (_key, value) = entry?;
        out.push(decode(value.value())?);
        if out.len() >= limit.max(1) {
            break;
        }
    }
    Ok(out)
}

pub(super) fn admin_create_rule(
    store: &RedbStore,
    text: &str,
    hint: &str,
    now_ms: u64,
) -> Result<Rule> {
    let text = text.trim().to_string();
    if text.is_empty() {
        return Err(Error::InvalidInput(
            "Validation failed: Text can't be blank".into(),
        ));
    }
    if text.chars().count() > crate::domain::RULE_TEXT_LIMIT {
        return Err(Error::InvalidInput(
            "Validation failed: Text is too long".into(),
        ));
    }
    let write = store.begin_write()?;
    let rule = Rule {
        id: store.next_id(),
        text,
        hint: hint.to_string(),
        created_at_ms: now_ms,
        updated_at_ms: now_ms,
    };
    {
        let mut table = write.open_table(RULES)?;
        table.insert(rule.id.value(), encode(&rule)?.as_slice())?;
    }
    write.commit()?;
    Ok(rule)
}

pub(super) fn admin_delete_rule(store: &RedbStore, id: Id) -> Result<bool> {
    let write = store.begin_write()?;
    let removed = {
        let mut table = write.open_table(RULES)?;
        table.remove(id.value())?.is_some()
    };
    write.commit()?;
    Ok(removed)
}

pub(super) fn admin_rules(store: &RedbStore) -> Result<Vec<Rule>> {
    let read = store.begin_read()?;
    let table = read.open_table(RULES)?;
    let mut out = Vec::new();
    for entry in table.range(0u64..)? {
        let (_, value) = entry?;
        out.push(decode(value.value())?);
    }
    Ok(out)
}

pub(super) fn admin_rules_by_ids(store: &RedbStore, ids: &[Id]) -> Result<Vec<Rule>> {
    let read = store.begin_read()?;
    let table = read.open_table(RULES)?;
    let mut out = Vec::with_capacity(ids.len());
    for id in ids {
        if let Some(guard) = table.get(id.value())? {
            out.push(decode(guard.value())?);
        }
    }
    Ok(out)
}

pub(super) fn admin_rule_translations(store: &RedbStore) -> Result<Vec<RuleTranslation>> {
    let read = store.begin_read()?;
    let table = read.open_table(RULE_TRANSLATIONS)?;
    let mut out = Vec::new();
    for entry in table.iter()? {
        let (_, value) = entry?;
        out.push(decode(value.value())?);
    }
    out.sort_by(|a: &RuleTranslation, b: &RuleTranslation| {
        a.rule_id
            .value()
            .cmp(&b.rule_id.value())
            .then_with(|| a.locale.cmp(&b.locale))
    });
    Ok(out)
}

pub(super) fn admin_set_rule_translation(
    store: &RedbStore,
    rule_id: Id,
    locale: String,
    text: String,
    hint: String,
    now_ms: u64,
) -> Result<RuleTranslation> {
    let locale = locale.trim().to_string();
    if locale.is_empty()
        || locale.len() > RULE_LOCALE_LIMIT
        || !locale
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'-')
    {
        return Err(Error::InvalidInput(format!(
            "rule locale {locale:?} is not a BCP-47 tag"
        )));
    }
    if text.chars().count() > RULE_TEXT_LIMIT {
        return Err(Error::InvalidInput(
            "Validation failed: Text is too long".into(),
        ));
    }
    let write = store.begin_write()?;
    {
        let rules = write.open_table(RULES)?;
        if rules.get(rule_id.value())?.is_none() {
            return Err(Error::NotFound(format!("rule {rule_id}")));
        }
    }
    let row = RuleTranslation {
        rule_id,
        locale: locale.clone(),
        text,
        hint,
        updated_at_ms: now_ms,
    };
    {
        let mut table = write.open_table(RULE_TRANSLATIONS)?;
        table.insert(
            super::schema::rule_translation_key(rule_id.value(), &locale).as_str(),
            encode(&row)?.as_slice(),
        )?;
    }
    write.commit()?;
    Ok(row)
}

pub(super) fn admin_delete_rule_translation(
    store: &RedbStore,
    rule_id: Id,
    locale: &str,
) -> Result<bool> {
    let write = store.begin_write()?;
    let removed = {
        let mut table = write.open_table(RULE_TRANSLATIONS)?;
        table
            .remove(super::schema::rule_translation_key(rule_id.value(), locale).as_str())?
            .is_some()
    };
    write.commit()?;
    Ok(removed)
}
